selector_to_html = {"a[href=\"#platform-environment-variables\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Platform environment variables<a class=\"headerlink\" href=\"#platform-environment-variables\" title=\"Link to this heading\">#</a></h2><p>FlagScale passes device visibility through the experiment-level YAML <code class=\"docutils literal notranslate\"><span class=\"pre\">envs</span></code> block. Each platform uses a different variable name.</p>", "a[href=\"#known-issues-and-workarounds\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">7. Known issues and workarounds<a class=\"headerlink\" href=\"#known-issues-and-workarounds\" title=\"Link to this heading\">#</a></h2><h3>7.1 MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">ImportError:</span> <span class=\"pre\">cannot</span> <span class=\"pre\">import</span> <span class=\"pre\">name</span> <span class=\"pre\">'AttrsDescriptor'</span> <span class=\"pre\">from</span> <span class=\"pre\">'triton.compiler.compiler'</span></code></strong> \u2014 after switching to FlagTree, PyTorch\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._inductor</span></code> cannot find <code class=\"docutils literal notranslate\"><span class=\"pre\">AttrsDescriptor</span></code>. Add a shim to <code class=\"docutils literal notranslate\"><span class=\"pre\">/opt/conda/lib/python3.12/site-packages/triton/compiler/compiler.py</span></code>:</p>", "a[href=\"#configure-the-training-task\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Configure the training task<a class=\"headerlink\" href=\"#configure-the-training-task\" title=\"Link to this heading\">#</a></h2><h3>4.1 Experiment-level YAML<a class=\"headerlink\" href=\"#experiment-level-yaml\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">examples/qwen3/conf/train.yaml</span></code> selects the task-level config and defines the runner environment:</p>", "a[href=\"#experiment-level-yaml\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.1 Experiment-level YAML<a class=\"headerlink\" href=\"#experiment-level-yaml\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">examples/qwen3/conf/train.yaml</span></code> selects the task-level config and defines the runner environment:</p>", "a[href=\"#install-flagscale\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Install FlagScale<a class=\"headerlink\" href=\"#install-flagscale\" title=\"Link to this heading\">#</a></h2><p>Verify, then install the logging dependencies used by the training runs:</p>", "a[href=\"#expected-output\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Expected output<a class=\"headerlink\" href=\"#expected-output\" title=\"Link to this heading\">#</a></h3><p>A healthy Ascend single-card run:</p>", "a[href=\"#notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">8. Notes<a class=\"headerlink\" href=\"#notes\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#component-versions-used\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Component versions used<a class=\"headerlink\" href=\"#component-versions-used\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#task-level-yaml\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.2 Task-level YAML<a class=\"headerlink\" href=\"#task-level-yaml\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">examples/qwen3/conf/train/0_6b.yaml</span></code> carries the model, dataset, and optimizer settings:</p>", "a[href=\"#metax\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">7.1 MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">ImportError:</span> <span class=\"pre\">cannot</span> <span class=\"pre\">import</span> <span class=\"pre\">name</span> <span class=\"pre\">'AttrsDescriptor'</span> <span class=\"pre\">from</span> <span class=\"pre\">'triton.compiler.compiler'</span></code></strong> \u2014 after switching to FlagTree, PyTorch\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._inductor</span></code> cannot find <code class=\"docutils literal notranslate\"><span class=\"pre\">AttrsDescriptor</span></code>. Add a shim to <code class=\"docutils literal notranslate\"><span class=\"pre\">/opt/conda/lib/python3.12/site-packages/triton/compiler/compiler.py</span></code>:</p>", "a[href=\"#t-head-ppu\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">7.4 T-Head PPU<a class=\"headerlink\" href=\"#t-head-ppu\" title=\"Link to this heading\">#</a></h3><p><strong>FlagTree and FlagGems cannot be compiled on <code class=\"docutils literal notranslate\"><span class=\"pre\">/workspace</span></code></strong> \u2014 <code class=\"docutils literal notranslate\"><span class=\"pre\">/workspace</span></code> is an OSS object-store FUSE mount (<code class=\"docutils literal notranslate\"><span class=\"pre\">ossfs2</span></code>) that cannot host in-place ELF writes. Build from local disk, keeping <code class=\"docutils literal notranslate\"><span class=\"pre\">.git</span></code> for <code class=\"docutils literal notranslate\"><span class=\"pre\">setuptools_scm</span></code>.</p><p><strong>FlagCX is not enabled</strong> \u2014 the FlagCX path is known to fail on this platform.</p>", "a[href=\"#run-on-the-flagos-operator-stack\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">6. Run on the FlagOS operator stack<a class=\"headerlink\" href=\"#run-on-the-flagos-operator-stack\" title=\"Link to this heading\">#</a></h2><p>To run the same job through FlagTree and FlagGems instead of the vendor operator library, use the <code class=\"docutils literal notranslate\"><span class=\"pre\">te_fl</span></code> configuration pair and select the FlagOS tier:</p>", "a[href=\"#hygon\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">7.2 Hygon<a class=\"headerlink\" href=\"#hygon\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">gradient_accumulation_fusion</span></code> needs APEX CUDA extensions</strong> \u2014 set <code class=\"docutils literal notranslate\"><span class=\"pre\">no_gradient_accumulation_fusion:</span> <span class=\"pre\">true</span></code> in the task config.</p><p><strong>JIT operator fusion fails</strong> \u2014 set <code class=\"docutils literal notranslate\"><span class=\"pre\">disable_jit_fuser:</span> <span class=\"pre\">true</span></code>.</p>", "a[href=\"requirements.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Requirements<a class=\"headerlink\" href=\"#requirements\" title=\"Link to this heading\">#</a></h1><p>This section includes information about the hardware platforms and models.</p>", "a[href=\"#multi-platform-training-and-testing\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-Platform Training and Testing<a class=\"headerlink\" href=\"#multi-platform-training-and-testing\" title=\"Link to this heading\">#</a></h1><p>FlagScale has no hardware requirements of its own \u2014 it orchestrates training through the FlagOS plugins. This guide shows how to drive an end-to-end training job on four non-NVIDIA platforms (MetaX, Hygon, Ascend, T-Head PPU) with the plugin stack underneath.</p><p>Platform-specific plugin installation is documented in the plugin guides:</p>", "a[href=\"#ascend\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">7.3 Ascend<a class=\"headerlink\" href=\"#ascend\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">TypeError:</span> <span class=\"pre\">'&lt;'</span> <span class=\"pre\">not</span> <span class=\"pre\">supported</span> <span class=\"pre\">between</span> <span class=\"pre\">instances</span> <span class=\"pre\">of</span> <span class=\"pre\">'NoneType'</span> <span class=\"pre\">and</span> <span class=\"pre\">'int'</span></code></strong> \u2014 <code class=\"docutils literal notranslate\"><span class=\"pre\">get_device_arch_version()</span></code> returns <code class=\"docutils literal notranslate\"><span class=\"pre\">None</span></code> on NPU because the device has no <code class=\"docutils literal notranslate\"><span class=\"pre\">.major</span></code> attribute. The path is only reached when <code class=\"docutils literal notranslate\"><span class=\"pre\">tensor_model_parallel_size</span> <span class=\"pre\">&gt;</span> <span class=\"pre\">1</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">context_parallel_size</span> <span class=\"pre\">&gt;</span> <span class=\"pre\">1</span></code>, so single-card runs pass and multi-card runs fail. Patch the function to return a value below 10 on non-NVIDIA devices:</p>", "a[href=\"#run-the-training-test\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">5. Run the training test<a class=\"headerlink\" href=\"#run-the-training-test\" title=\"Link to this heading\">#</a></h2><p>Monitor device utilization in a second shell:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
